var USE_SVG = false;
var env;

function setup() {
	createCanvas(S=max(windowWidth, windowHeight), S, USE_SVG ? SVG : P2D);
	if (!USE_SVG) describe("generated landscape with hills, sun or moon, street and some power poles");	
  background(212)

  env = {
    BG: color(0, 0, 8),
    horizon: random(0.35, 0.65) * height,
    streetStart: random(0.65, 0.8) * width,
    streetEnd: random(0.5, 0.6) * width,
    sun: {
      x: random(width),
      y: randomGaussian(0, 12),
      d: random(0.15, 0.2) * max(width, height),
    },
  };

  noFill();
  stroke(0);
  loop();
}

function draw() {
  // background(env.BG);

  // sun
  if (env.sun.y - env.sun.d > 0) {    
    // circle(env.sun.x, env.sun.y, env.sun.d);
  } else {
var dy = 7
var da = 0.01;
    arc(env.sun.x, env.sun.y, env.sun.d, env.sun.d, -da, PI+da);
  }

  // hills
  {
    push();
    // fill(env.BG)
    beginShape();
    vertex(-1, env.horizon)
var hillPts = [];
    for (let x = -1, dx = 1, ly = 0; x < width*1.1; x += dx) {
      dx = ~~(random(0.05, 0.1) * width);
var y = ~~(noise(x) * env.horizon);
      vertex(x, y);
      hillPts.push({x, y})
    }
    // vertex(width+1, noise(width) * random(env.horizon));
    vertex(width, env.horizon)
    endShape();

    // overlaps
    // console.table(hillPts)
    for (let i = 1; i < hillPts.length-1; i++) {
var pdy = hillPts[i].y - hillPts[i-1].y;
var pdx = hillPts[i].x - hillPts[i-1].x;
var ndy = hillPts[i+1].y - hillPts[i].y;
var ndx = hillPts[i+1].x - hillPts[i].x;
var ny = hillPts[i+1].y;
var nx = hillPts[i+1].x;
      if (ny < hillPts[i].y+pdy/2) {
var eP = {x: hillPts[i].x-pdx/2, y: hillPts[i].y-pdy/2}
var m1 = ndy/ndx;
var m2 = pdy/pdx;
        // console.log(hillPts[i].x, hillPts[i].y, m1, m2)
        if (m1 < 0 && m2 < 0 && m1 > m2)  {
          // dont draw
        } else {
          line(hillPts[i].x, hillPts[i].y, hillPts[i].x+pdx/2, hillPts[i].y+pdy/2)
        }
      }
    }

    pop();
  }

  // horizon
  {
    push()
    // line(0, env.horizon, width, env.horizon);
    // fill(env.BG);
    rect(-1, env.horizon, width+2, height-env.horizon+1)
    pop();
  }

  // street
  { 
var d = random(0.01, 0.02) * width;
var df = random(8, 10);
    line(
      env.streetStart - d, env.horizon,
      env.streetEnd - d * df, height
    );
    line(
      env.streetStart + d, env.horizon,
      env.streetEnd + d * df, height
    );
    push();
    drawingContext.setLineDash([10]);
    line(
      env.streetStart, env.horizon,
      env.streetEnd, height
    );
    pop();

  // }

  // masts
  // {
var wirePts = [];
var num = (1 - env.horizon / height) * 10 / 1.5;
    for (let i = 0; i <= num; i++) {
      var y = env.horizon + i * i * height/23;
var x = map(y, env.horizon, height, env.streetStart - 4*d, env.streetEnd - 4*d*df)
var f = map(y, env.horizon, height, 1.2, 1.8)
var h = pow(15, f);
      line(x, y, x, y - h);
      line(x-h/3, y-h*0.9, x+h/3, y-h*0.9);
      wirePts.push({x: x+h/4, y: y-h*0.9})
    }
    // console.log(wirePts)
    // wires
    for (let i = 1; i < wirePts.length; i++) {
var a = wirePts[i-1];
var b = wirePts[i];
      var d = dist(a.x, a.y, b.x, b.y);
      bezier(a.x, a.y, a.x-d/3, a.y+d/3, b.x+d/3, b.y+d/3, b.x, b.y)
    }
    {
      var a = wirePts[wirePts.length-1];
      var b = {x: 0, y: height}
      bezier(a.x, a.y, a.x, lerp(a.y, height, 0.5), b.x, b.y, b.x, b.y)
    }

  }

  // tree
  {
    var x = randomGaussian(width*0.85, 15);
    var y = randomGaussian(height*0.8, 15);
    var d = randomGaussian(max(width, height)*0.1, 15);

    var a = 1.3;
    arc(x-d/3, y, d, d, 1.1, -1.65);
    arc(x+d/3, y, d, d, PI + 1.65, PI - 1.1);
    arc(x, y-d/2, d, d, TWO_PI-HALF_PI-1.4, TWO_PI-HALF_PI+1.4)
    line(x, y-d/2, x-d/8, y+d)
    line(x, y-d/2, x+d/8, y+d)
  }


  // noLoop() removed for animation
}

function keyPressed() {
	if (key === 's' || key === 'S') {
		save("epi_landscape.svg"); // Save the canvas as SVG
	}
}
